// ===== Prepare: parse Telegram update, route it, load session =====
const ADMIN_IDS = ['REPLACE_WITH_ADMIN_TELEGRAM_USER_ID']; // only these users may upload documents
const MAX_HISTORY = 8;                                     // last N messages kept per chat
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;                // forget idle chats after 24h

const msg = $input.first().json.message || {};
const from = msg.from || {};
const chat_id = msg.chat?.id;
const user_name = [from.first_name, from.last_name].filter(Boolean).join(' ') || 'Customer';
const username = from.username || null;
const text = (msg.text || '').trim();
const isAdmin = ADMIN_IDS.includes(String(from.id));
const base = { chat_id, user_name, username, text };
const lang_hint = /[\u0600-\u06FF]/.test(text) ? 'ar' : 'en';
const both = (ar, en) => `${ar}\n\n${en}`;

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const now = Date.now();
for (const [k, s] of Object.entries(store.sessions)) {
  if (now - (s.updated || 0) > SESSION_TTL_MS) delete store.sessions[k];
}
const key = String(chat_id);

// Documents: admin -> ingest, everyone else -> polite refusal
if (msg.document) {
  if (isAdmin) {
    return [{ json: { ...base, route: 'ingest', file_id: msg.document.file_id, file_name: msg.document.file_name || 'document' } }];
  }
  return [{ json: { ...base, route: 'reply_only', reply: both('أنا بقرأ الرسائل النصية بس 🙏', 'I can only read text messages 🙏') } }];
}
if (!text) {
  return [{ json: { ...base, route: 'reply_only', reply: both('ابعتلي رسالة نصية من فضلك 🙏', 'Please send a text message 🙏') } }];
}

// Commands
if (text.startsWith('/start')) {
  delete store.sessions[key];
  return [{ json: { ...base, route: 'reply_only', reply: both(
    'أهلاً بيك في Smile Clinic 😁\nاسألني عن الأسعار والمواعيد والخدمات، أو قولّي "عايز أحجز" وأنا أظبطلك الحجز.\n/human للتحدث مع موظف • /cancel لإلغاء الحجز الجاري',
    'Welcome to Smile Clinic 😁\nAsk me about prices, hours and services, or say "I want to book" and I will set it up.\n/human to talk to a person • /cancel to cancel the booking in progress') } }];
}
if (text.startsWith('/cancel')) {
  delete store.sessions[key];
  return [{ json: { ...base, route: 'reply_only', reply: both('تمام، لغيت الحجز الجاري. أقدر أساعدك في حاجة تانية؟', 'Done, I cancelled the booking in progress. Anything else I can help with?') } }];
}
if (text.startsWith('/human')) {
  return [{ json: { ...base, route: 'handoff',
    reply: both('تمام، هحوّلك لحد من الفريق وهيرد عليك هنا قريب 🙋', 'Sure, I am passing you to a team member. They will reply here shortly 🙋'),
    staff_text: `🙋 Human requested\nCustomer: ${user_name}${username ? ' (@' + username + ')' : ''}\nChat ID: ${chat_id}\nOpen chat: tg://user?id=${chat_id}` } }];
}

// Normal chat: load/update session
const s = store.sessions[key] || { history: [], draft: {} };
s.history.push({ role: 'user', text });
s.history = s.history.slice(-MAX_HISTORY);
s.updated = now;
store.sessions[key] = s;

return [{ json: { ...base, route: 'chat', lang_hint, history: s.history, draft: s.draft } }];

// ===== Build prompt: merge RAG passages + session into one LLM prompt =====
const CONFIG = { CLINIC: 'Smile Clinic', TZ: 'Africa/Cairo', OPEN: '10:00', CLOSE: '22:00' };

const p = $('Prepare').first().json;
const rag = $input.first().json || {};                      // empty/{error} if the API call failed
const passages = Array.isArray(rag.passages) ? rag.passages : [];
const top_score = Number(rag.top_score ?? passages[0]?.score ?? 0) || 0;

const context = passages.map((x, i) =>
  `[${i + 1}] (source: ${x.source || 'unknown'}${x.section ? ' / ' + x.section : ''}) ${x.text}`
).join('\n\n') || '(no relevant passages found)';

const today = new Date().toLocaleDateString('en-CA', { timeZone: CONFIG.TZ });
const weekday = new Date().toLocaleDateString('en-US', { timeZone: CONFIG.TZ, weekday: 'long' });
const draft = { ...(p.draft || {}) };
const summaryShown = !!draft.awaiting_confirm;
delete draft.awaiting_confirm;
const history = (p.history || []).slice(0, -1)
  .map(m => `${m.role === 'user' ? 'Customer' : 'Assistant'}: ${m.text}`).join('\n') || '(none)';

const prompt = `You are the virtual receptionist of ${CONFIG.CLINIC}, chatting with customers on Telegram.
Today is ${weekday}, ${today} (timezone ${CONFIG.TZ}). Bookings are accepted between ${CONFIG.OPEN} and ${CONFIG.CLOSE}.

RULES
1. Answer questions ONLY from the CONTEXT below. Never invent prices, hours, doctors or policies. If the answer is not in the CONTEXT, set "answerable" to false.
2. Reply in the customer's language (Arabic or English; Egyptian Arabic dialect is fine). Be polite and brief.
3. End factual answers with the source name, e.g. (Source: price list).
4. Never give medical or legal advice: use intent "human_request".
5. Booking: collect service, date, time, name and phone. Ask only for what is missing, one or two items at a time. Never guess values. Convert relative dates (tomorrow, بكرة, next Sunday) to YYYY-MM-DD using today's date, and times to 24h HH:MM.
6. Always return the full current booking details in "booking": start from CURRENT_BOOKING_DRAFT and change only what the customer just said. Use null for unknown values.
7. Set "confirmed" to true ONLY if SUMMARY_ALREADY_SHOWN is true and the customer's latest message clearly agrees to it. Otherwise false.
8. intent is one of: faq, booking, complaint, human_request, other.

OUTPUT: return ONLY one JSON object, no markdown, in this shape:
{"intent":"faq","language":"ar","answerable":true,"reply":"...","booking":{"service":null,"date":null,"time":null,"name":null,"phone":null},"confirmed":false}

CONTEXT:
${context}

CURRENT_BOOKING_DRAFT: ${JSON.stringify(draft)}
SUMMARY_ALREADY_SHOWN: ${summaryShown}

CONVERSATION SO FAR:
${history}

CUSTOMER (latest message): ${p.text}`;

return [{ json: { prompt, top_score, passages_n: passages.length } }];

// ===== Process LLM: parse JSON, enforce business rules, decide the next action =====
const CONFIG = {
  TZ: 'Africa/Cairo',
  OPEN: '10:00', CLOSE: '22:00', SLOT_MIN: 30,   // keep in sync with 02_branches_and_hours.md
  CLOSED_WEEKDAYS: [],                           // 0=Sun ... 6=Sat, e.g. [5] if closed on Fridays
  SCORE_THRESHOLD: 0.55,                         // starting point, tune on your test set
  MAX_HISTORY: 8,
};
const FIELDS = ['service', 'date', 'time', 'name', 'phone'];

const prep = $('Prepare').first().json;
const ctx = $('Build prompt').first().json;
const raw = $input.first().json || {};
const out = String(raw.text ?? raw.output ?? raw.response ?? '');

let llm;
try { const m = out.match(/\{[\s\S]*\}/); llm = JSON.parse(m ? m[0] : out); } catch (e) { llm = null; }
const parseFailed = !llm || typeof llm !== 'object';
if (parseFailed) llm = { intent: 'other', language: prep.lang_hint };
const lang = (llm.language || prep.lang_hint) === 'ar' ? 'ar' : 'en';

const T = {
  ar: {
    notSure: 'مش متأكد من الإجابة دي، فهحوّل سؤالك لحد من الفريق وهيرد عليك قريب 🙏',
    handoff: 'تمام، هحوّلك لحد من الفريق وهيرد عليك هنا قريب 🙋',
    fail: 'حصلت مشكلة مؤقتة عندي، فهحوّل رسالتك لحد من الفريق وهيرد عليك قريب 🙏',
    pastDate: 'التاريخ ده مش مظبوط أو عدّى. ممكن تقولي تاريخ تاني؟',
    closedDay: 'العيادة مقفولة في اليوم ده. ممكن تختار يوم تاني؟',
    badTime: `المواعيد المتاحة من ${CONFIG.OPEN} لحد ${CONFIG.CLOSE}. ممكن تختار ميعاد في الفترة دي؟`,
    pastTime: 'الميعاد ده عدّى النهارده. ممكن تختار ميعاد بعد الوقت الحالي؟',
    badPhone: 'رقم الموبايل شكله مش مظبوط. ممكن تبعته تاني بالصيغة الكاملة؟',
    summary: d => `راجع الحجز من فضلك:\n• الخدمة: ${d.service}\n• التاريخ: ${d.date}\n• الوقت: ${d.time}\n• الاسم: ${d.name}\n• الموبايل: ${d.phone}\n\nاكتب "نعم" للتأكيد، أو قولّي لو في تعديل.`,
  },
  en: {
    notSure: "I'm not fully sure about that, so I'm passing your question to a team member who will reply shortly 🙏",
    handoff: "Sure, I'm passing you to a team member. They'll reply here shortly 🙋",
    fail: 'I hit a temporary problem, so I am passing your message to a team member who will reply shortly 🙏',
    pastDate: 'That date is invalid or already past. Could you give me another date?',
    closedDay: 'The clinic is closed on that day. Could you pick another day?',
    badTime: `Bookings are available between ${CONFIG.OPEN} and ${CONFIG.CLOSE}. Could you pick a time in that window?`,
    pastTime: 'That time has already passed today. Could you pick a later time?',
    badPhone: 'That phone number looks invalid. Could you send it again in full?',
    summary: d => `Please review your booking:\n• Service: ${d.service}\n• Date: ${d.date}\n• Time: ${d.time}\n• Name: ${d.name}\n• Phone: ${d.phone}\n\nReply "yes" to confirm, or tell me what to change.`,
  },
}[lang];

// ---- time helpers (Cairo) ----
const toMin = t => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
const nowDate = new Date().toLocaleDateString('en-CA', { timeZone: CONFIG.TZ });
const nowTime = new Date().toLocaleTimeString('en-GB', { timeZone: CONFIG.TZ, hour12: false, hour: '2-digit', minute: '2-digit' }).replace(/^24/, '00');

// ---- merge draft ----
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const key = String(prep.chat_id);
const sess = store.sessions[key] || { history: [], draft: {} };

const draft = { ...(prep.draft || {}) };
const before = JSON.stringify(FIELDS.map(k => draft[k] || null));
const b = (llm.booking && typeof llm.booking === 'object') ? llm.booking : {};
if (llm.intent === 'booking' || FIELDS.some(k => draft[k])) {
  for (const k of FIELDS) {
    const v = b[k];
    if (v !== null && v !== undefined && String(v).trim() !== '') draft[k] = String(v).trim();
  }
}

// ---- validate (code decides, not the model) ----
const issues = [];
if (draft.date) {
  const okFmt = /^\d{4}-\d{2}-\d{2}$/.test(draft.date) && !isNaN(Date.parse(draft.date));
  if (!okFmt || draft.date < nowDate) { issues.push(T.pastDate); delete draft.date; }
  else if (CONFIG.CLOSED_WEEKDAYS.includes(new Date(draft.date + 'T12:00:00Z').getUTCDay())) { issues.push(T.closedDay); delete draft.date; }
}
if (draft.time) {
  const okFmt = /^([01]\d|2[0-3]):[0-5]\d$/.test(draft.time);
  const inHours = okFmt && toMin(draft.time) >= toMin(CONFIG.OPEN) && toMin(draft.time) + CONFIG.SLOT_MIN <= toMin(CONFIG.CLOSE);
  if (!inHours) { issues.push(T.badTime); delete draft.time; }
  else if (draft.date === nowDate && toMin(draft.time) <= toMin(nowTime)) { issues.push(T.pastTime); delete draft.time; }
}
if (draft.phone) {
  const digits = draft.phone.replace(/[\s\-()]/g, '');
  if (/^\+?\d{10,15}$/.test(digits)) draft.phone = digits;
  else { issues.push(T.badPhone); delete draft.phone; }
}

const after = JSON.stringify(FIELDS.map(k => draft[k] || null));
const changed = before !== after;
const complete = FIELDS.every(k => draft[k]);
const who = `${prep.user_name}${prep.username ? ' (@' + prep.username + ')' : ''}`;

// ---- decide ----
let action = 'reply';
let reply = String(llm.reply || '').trim();
let staff_text = null;
let booking = null;
const staff = reason => `🙋 ${reason}\nCustomer: ${who}\nChat ID: ${prep.chat_id}\nOpen chat: tg://user?id=${prep.chat_id}\nLast message: ${prep.text}`;

if (parseFailed) {
  action = 'handoff'; reply = T.fail; staff_text = staff('Bot error (LLM unavailable or invalid output)');
} else if (llm.intent === 'complaint' || llm.intent === 'human_request') {
  action = 'handoff'; reply = reply || T.handoff; staff_text = staff(llm.intent === 'complaint' ? 'Complaint' : 'Human requested');
} else if (llm.intent === 'faq' && (llm.answerable === false || ctx.top_score < CONFIG.SCORE_THRESHOLD)) {
  action = 'handoff'; reply = T.notSure; staff_text = staff('Low-confidence question');
} else if (issues.length) {
  reply = issues[0]; draft.awaiting_confirm = false;
} else if (complete) {
  if (draft.awaiting_confirm && !changed && llm.confirmed === true) {
    action = 'create_booking';
    const d = nowDate.replace(/-/g, '');
    booking = { booking_id: `BK-${d}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`, created_at: new Date().toISOString(), chat_id: prep.chat_id, ...Object.fromEntries(FIELDS.map(k => [k, draft[k]])) };
  } else if (llm.intent === 'booking' || changed) {
    draft.awaiting_confirm = true; reply = T.summary(draft);
  }
} else {
  draft.awaiting_confirm = false;
}
if (!reply) reply = T.fail;

// ---- persist session (create_booking is finalised by the later nodes) ----
sess.draft = draft;
if (action !== 'create_booking') sess.history.push({ role: 'assistant', text: reply });
sess.history = sess.history.slice(-CONFIG.MAX_HISTORY);
sess.updated = Date.now();
store.sessions[key] = sess;

return [{ json: {
  chat_id: prep.chat_id, user_name: prep.user_name, username: prep.username, text: prep.text,
  intent: llm.intent || 'other', lang, top_score: ctx.top_score, action, reply, staff_text, booking,
  answered_by: action === 'handoff' ? 'human' : 'bot',
} }];

// ===== Slot decision: is the requested slot still free? =====
const p = $('Process LLM').first().json;
const bk = p.booking;
const rows = $input.all().map(i => i.json).filter(r => r && r.date && r.time);
const taken = rows.some(r =>
  String(r.date).trim() === bk.date &&
  String(r.time).trim() === bk.time &&
  String(r.status || 'confirmed').toLowerCase() !== 'cancelled');

if (!taken) return [{ json: { ...p, slot_free: true } }];

const reply = p.lang === 'ar'
  ? 'الميعاد ده محجوز بالفعل 🙏 ممكن تختار وقت تاني؟'
  : 'That time slot is already booked 🙏 Could you pick another time?';

const store = $getWorkflowStaticData('global');
const sess = store.sessions?.[String(p.chat_id)];
if (sess) {
  delete sess.draft.time;
  sess.draft.awaiting_confirm = false;
  sess.history.push({ role: 'assistant', text: reply });
}
return [{ json: { chat_id: p.chat_id, reply, slot_free: false } }];

// ===== Booking confirmed: build replies, clear the draft =====
const p = $('Slot decision').first().json;
const bk = p.booking;

const reply = p.lang === 'ar'
  ? `تم تأكيد حجزك ✅\n• رقم الحجز: ${bk.booking_id}\n• الخدمة: ${bk.service}\n• التاريخ: ${bk.date}\n• الوقت: ${bk.time}\nهنستناك! لو عايز تغيّر حاجة اكتب /human.`
  : `Your booking is confirmed ✅\n• Booking ID: ${bk.booking_id}\n• Service: ${bk.service}\n• Date: ${bk.date}\n• Time: ${bk.time}\nSee you then! To change anything, type /human.`;

const staff_text = `📅 New booking ${bk.booking_id}\nName: ${bk.name}\nPhone: ${bk.phone}\nService: ${bk.service}\nWhen: ${bk.date} ${bk.time}\nTelegram: ${p.username ? '@' + p.username : 'tg://user?id=' + p.chat_id}`;

const store = $getWorkflowStaticData('global');
const sess = store.sessions?.[String(p.chat_id)];
if (sess) {
  sess.draft = {};
  sess.history.push({ role: 'assistant', text: reply });
}
return [{ json: { chat_id: p.chat_id, reply, staff_text } }];
